package com.servlet;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.sql.*;import com.db.DbConnect;import com.dao.*;import com.entity.*;import com.util.PasswordUtil;@WebServlet(urlPatterns={"/user-register","/user-login","/doctor-login","/admin-login","/logout","/book-appointment","/request-consultation","/doctor/update-appointment","/doctor/save-consultation","/admin/add-doctor"})public class AppServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException{if(q.getServletPath().equals("/logout")){HttpSession h=q.getSession(false);if(h!=null)h.invalidate();s.sendRedirect(q.getContextPath()+"/index.jsp");}}protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{String p=q.getServletPath();try(Connection c=DbConnect.getConn()){if(p.equals("/user-register")){User u=new User(q.getParameter("fullName"),q.getParameter("email"),q.getParameter("password"));q.getSession().setAttribute("msg",new UserDao(c).register(u)?"Registration successful. Please login.":"Registration failed.");s.sendRedirect("signup.jsp");return;}if(p.equals("/user-login")){User u=new UserDao(c).login(q.getParameter("email"),q.getParameter("password"));if(u!=null){q.getSession().setAttribute("userObj",u);s.sendRedirect("patient/dashboard.jsp");}else{s.sendRedirect("user_login.jsp");}return;}if(p.equals("/doctor-login")){Doctor d=new DoctorDao(c).login(q.getParameter("email"),q.getParameter("password"));if(d!=null){q.getSession().setAttribute("doctorObj",d);s.sendRedirect("doctor/dashboard.jsp");}else{s.sendRedirect("doctor_login.jsp");}return;}if(p.equals("/admin-login")){PreparedStatement z=c.prepareStatement("SELECT password_hash FROM admins WHERE email=?");z.setString(1,q.getParameter("email"));ResultSet r=z.executeQuery();if(r.next()&&PasswordUtil.matches(q.getParameter("password"),r.getString(1))){q.getSession().setAttribute("adminEmail",q.getParameter("email"));s.sendRedirect("admin/dashboard.jsp");}else{s.sendRedirect("admin_login.jsp");}return;}if(p.equals("/book-appointment")){User u=(User)q.getSession().getAttribute("userObj");Appointment a=new Appointment();a.userId=u.getId();a.doctorId=Integer.parseInt(q.getParameter("doctorId"));a.patientName=q.getParameter("patientName");a.gender=q.getParameter("gender");a.age=Integer.parseInt(q.getParameter("age"));a.appointmentDate=q.getParameter("appointmentDate");a.email=q.getParameter("email");a.phone=q.getParameter("phone");a.disease=q.getParameter("disease");a.address=q.getParameter("address");new AppointmentDao(c).create(a);s.sendRedirect("patient/book_appointment.jsp");return;}if(p.equals("/request-consultation")){User u=(User)q.getSession().getAttribute("userObj");Consultation x=new Consultation();x.userId=u.getId();x.doctorId=Integer.parseInt(q.getParameter("doctorId"));x.requestedDate=q.getParameter("requestedDate").replace('T',' ')+":00";x.mode=q.getParameter("mode");x.reason=q.getParameter("reason");new ConsultationDao(c).create(x);s.sendRedirect("patient/consultations.jsp");return;}if(p.equals("/doctor/update-appointment")){Doctor d=(Doctor)q.getSession().getAttribute("doctorObj");new AppointmentDao(c).status(Integer.parseInt(q.getParameter("appointmentId")),d.getId(),q.getParameter("status"));s.sendRedirect("appointments.jsp");return;}if(p.equals("/doctor/save-consultation")){Doctor d=(Doctor)q.getSession().getAttribute("doctorObj");new ConsultationDao(c).update(Integer.parseInt(q.getParameter("consultationId")),d.getId(),q.getParameter("status"),q.getParameter("meetingLink"),q.getParameter("doctorNotes"),q.getParameter("prescription"));s.sendRedirect("consultations.jsp");return;}if(p.equals("/admin/add-doctor")){Doctor d=new Doctor();d.setFullName(q.getParameter("fullName"));d.setQualification(q.getParameter("qualification"));d.setSpecialist(q.getParameter("specialist"));d.setEmail(q.getParameter("email"));d.setPhone(q.getParameter("phone"));d.setPassword(q.getParameter("password"));new DoctorDao(c).add(d);s.sendRedirect("add_doctor.jsp");return;}}catch(Exception e){e.printStackTrace();s.sendError(500,"Operation failed. Check database configuration and server log.");}}}